sp_widget.client_script:
api.controller = function($scope, $window, $location) {

  var c = this;

  // ── Stats counter ─────────────────────────────────────────────────────────
  c.countByBadge = function(badgeClass) {
    if (!c.data || !c.data.applications) return 0;
    return c.data.applications.filter(function(a) {
      return a.badge_class === badgeClass;
    }).length;
  };

  // ── View Modal ────────────────────────────────────────────────────────────
  c.modalOpen = false;
  c.selected  = {};
  c.activeTab = 'personal';

  c.openModal = function(app) {
    c.selected  = app;
    c.activeTab = 'personal';
    c.modalOpen = true;
    document.body.style.overflow = 'hidden';
  };

  c.closeModal = function() {
    c.modalOpen = false;
    c.selected  = {};
    document.body.style.overflow = '';
  };

  c.setTab = function(tab) { c.activeTab = tab; };

  // ── Utilities ─────────────────────────────────────────────────────────────
  c.formatBytes = function(bytes) {
    if (!bytes || bytes == 0) return '0 B';
    var b = parseInt(bytes);
    if (b < 1024)    return b + ' B';
    if (b < 1048576) return (b / 1024).toFixed(1) + ' KB';
    return (b / 1048576).toFixed(1) + ' MB';
  };

  c.getFileIcon = function(ct) {
    if (!ct) return 'fa-file-o';
    if (ct.indexOf('pdf')   > -1) return 'fa-file-pdf-o';
    if (ct.indexOf('image') > -1) return 'fa-file-image-o';
    if (ct.indexOf('word')  > -1) return 'fa-file-word-o';
    if (ct.indexOf('excel') > -1 || ct.indexOf('sheet') > -1) return 'fa-file-excel-o';
    return 'fa-file-o';
  };

  // ── Navigation ────────────────────────────────────────────────────────────
  c.goBack = function() {
    $location.url('/applicant?id=applicant_dashboard');
  };

  // ── Timeline Toggle ───────────────────────────────────────────────────────
  c.expandedApp = null;
  c.appTimeline = [];

  c.toggleTimeline = function(app) {
    if (c.expandedApp === app.sys_id) {
      c.expandedApp = null;
      c.appTimeline = [];
      return;
    }
    c.expandedApp = app.sys_id;
    c.appTimeline = (c.data.timelines && c.data.timelines[app.sys_id]) || [];
  };

  // ── Escape closes modal ───────────────────────────────────────────────────
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      $scope.$apply(function() {
        if (c.modalOpen) c.closeModal();
      });
    }
  });

};

sp_widget.css:
/* =========================================================
   GATENOW · APPLICATION STATUS
   Service Portal widget · CSS

   Re-themed to match the GateNow marketing site (hero/about
   widgets): Outfit type, navy/blue palette, pill controls,
   soft rounded cards, airy blue-tinted shadows.

   Drop-in replacement — HTML class names are unchanged, so
   the existing template does not need to be touched.
   ========================================================= */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}

$gn-navy:       #0a2540;
$gn-blue:       #1560e0;
$gn-blue-dk:    #0f4cbb;
$gn-blue-soft:  #e8f0fe;
$gn-blue-tint:  #dbe7fa;
$gn-body:       #55677f;
$gn-hair:       #e4eaf4;
$gn-white:      #ffffff;
$gn-bg:         #f4f8fe;

$gn-amber:      #b5790a;
$gn-amber-soft: #fdf1dc;
$gn-purple:     #6a3fd6;
$gn-purple-soft:#efe9fd;
$gn-green:      #157a4c;
$gn-green-soft: #e2f6ec;
$gn-red:        #c53434;
$gn-red-soft:   #fceaea;

$gn-shadow-soft: 0 12px 30px rgba(16, 54, 110, 0.10);
$gn-shadow-card: 0 4px 16px rgba(16, 54, 110, 0.08);
$gn-shadow-btn:  0 14px 30px rgba(21, 96, 224, 0.30);

$gn-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;

/* ---------------------------------------------------------
   Base layout & wrapper
   --------------------------------------------------------- */

.gn-layout {
  background-color: $gn-bg;
  background-image:
    radial-gradient(700px 420px at 100% -8%, rgba(206, 226, 252, 0.55), rgba(206, 226, 252, 0) 68%),
    radial-gradient(560px 380px at 0% 100%, rgba(226, 238, 253, 0.55), rgba(226, 238, 253, 0) 64%);
  min-height: 100vh;
  font-family: $gn-font;
  color: $gn-navy;
}

.gn-layout *,
.gn-layout *::before,
.gn-layout *::after { box-sizing: border-box; }

.mya-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 24px 64px;
}

/* ---------------------------------------------------------
   Page header
   --------------------------------------------------------- */

.mya-page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  width: 100%;
}

.mya-page-hd-left {
  display: flex;
  align-items: center;
  text-align: left;
  gap: 18px;
}

.mya-page-hd-icon {
  background: $gn-white;
  width: 52px;
  height: 52px;
  min-width: 52px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: $gn-blue;
  box-shadow: $gn-shadow-card;
  margin: 0;
}

.mya-page-hd-left > div {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.mya-page-title {
  font-size: 27px;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin: 0 0 4px 0;
  color: $gn-navy;
  line-height: 1.2;
}

.mya-page-sub {
  font-size: 14.5px;
  font-weight: 400;
  color: $gn-body;
  margin: 0;
}

.mya-btn-back {
  background: $gn-white;
  border: 1px solid $gn-hair;
  padding: 10px 20px;
  border-radius: 999px;
  font-family: $gn-font;
  font-size: 14px;
  font-weight: 600;
  color: $gn-navy;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  box-shadow: $gn-shadow-card;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.mya-btn-back:hover {
  box-shadow: $gn-shadow-soft;
  transform: translateY(-1px);
}

/* ---------------------------------------------------------
   Breadcrumb
   --------------------------------------------------------- */

.mya-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  margin-bottom: 28px;
}

.mya-bc-cur {
  font-weight: 500;
  color: $gn-body;
}

/* ---------------------------------------------------------
   Stats bar — soft cards with a tinted icon chip, no heavy
   solid borders. Semantic hues kept for quick scanning but
   pulled into the same muted, pastel register as the rest
   of the theme.
   --------------------------------------------------------- */

.mya-stats-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 32px;
  align-items: stretch;
}

.mya-stat {
  flex: 1 1 190px;
  max-width: 250px;
  background: $gn-white;
  padding: 20px 22px;
  border-radius: 20px;
  box-shadow: $gn-shadow-card;
  display: flex;
  align-items: center;
  gap: 16px;
  border: 1px solid $gn-hair;
  margin: 0;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.mya-stat:hover {
  transform: translateY(-2px);
  box-shadow: $gn-shadow-soft;
}

.mya-stat > div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
}

.mya-stat i {
  width: 42px;
  height: 42px;
  min-width: 42px;
  border-radius: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}

.mya-stat--blue i      { background: $gn-blue-soft;   color: $gn-blue; }
.mya-stat--amber i     { background: $gn-amber-soft;  color: $gn-amber; }
.mya-stat--purple i    { background: $gn-purple-soft; color: $gn-purple; }
.mya-stat--green i     { background: $gn-green-soft;  color: $gn-green; }
.mya-stat--red i       { background: $gn-red-soft;    color: $gn-red; }

.mya-stat-val {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: $gn-navy;
  display: block;
  line-height: 1;
  margin-bottom: 4px;
}

.mya-stat-lbl {
  font-size: 12.5px;
  font-weight: 500;
  color: $gn-body;
  margin: 0;
  line-height: 1.2;
}

/* ---------------------------------------------------------
   Application list & cards
   --------------------------------------------------------- */

.mya-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.mya-app-card {
  background: $gn-white;
  border-radius: 20px;
  box-shadow: $gn-shadow-card;
  position: relative;
  overflow: hidden;
  transition: box-shadow 0.22s ease, transform 0.22s ease;
  border: 1px solid $gn-hair;
}

.mya-app-card:hover {
  box-shadow: $gn-shadow-soft;
}

/* thin top accent instead of a heavy left bar, echoing the
   hover rule on the homepage's about panels */
.mya-card-accent {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: auto;
  height: 3px;
  width: auto;
}

.badge-completed,
.mya-card-accent.badge-completed { background-color: $gn-green; }

.badge-review,
.mya-card-accent.badge-review { background-color: $gn-amber; }

.badge-declined,
.mya-card-accent.badge-declined { background-color: $gn-red; }

.badge-new,
.mya-card-accent.badge-new { background-color: $gn-blue; }

.badge-in-progress,
.mya-card-accent.badge-in-progress { background-color: $gn-purple; }

.mya-card-body {
  display: flex;
  align-items: center;
  padding: 22px 26px;
  cursor: pointer;
  flex-wrap: wrap;
  gap: 20px;
}

.mya-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.mya-col-app {
  flex: 2;
  min-width: 220px;
  flex-direction: row;
  align-items: center;
  gap: 16px;
}

.mya-app-av {
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: $gn-blue-soft;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  color: $gn-blue;
}

.mya-app-num {
  font-weight: 600;
  color: $gn-navy;
  font-size: 15px;
  letter-spacing: -0.005em;
}

.mya-app-date {
  font-size: 12.5px;
  font-weight: 400;
  color: $gn-body;
  margin-top: 4px;
}

.mya-col-prog {
  flex: 2;
  min-width: 180px;
}

.mya-prog-label,
.mya-date-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: $gn-blue;
  opacity: 0.75;
  margin-bottom: 4px;
}

.mya-prog-name {
  font-size: 14px;
  font-weight: 500;
  color: $gn-navy;
}

.mya-prog-num,
.mya-prog-none {
  font-size: 12.5px;
  font-weight: 400;
  color: $gn-body;
}

.mya-col-status {
  flex: 1.5;
  min-width: 150px;
}

/* pill badges, soft tint + matching text colour rather than
   a solid block — matches the eyebrow/tag treatment used on
   the homepage */
.mya-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 16px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: -0.005em;
}

.mya-badge.badge-completed   { background: $gn-green-soft;  color: $gn-green; }
.mya-badge.badge-review      { background: $gn-amber-soft;  color: $gn-amber; }
.mya-badge.badge-declined    { background: $gn-red-soft;    color: $gn-red; }
.mya-badge.badge-new         { background: $gn-blue-soft;   color: $gn-blue; }
.mya-badge.badge-in-progress { background: $gn-purple-soft; color: $gn-purple; }

.mya-col-date {
  flex: 1.5;
  min-width: 130px;
}

.mya-date-val {
  font-size: 13px;
  font-weight: 400;
  color: $gn-body;
}

.mya-col-actions {
  flex: 0.5;
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  min-width: 80px;
}

.mya-act-btn {
  background: $gn-blue-soft;
  border: none;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $gn-blue;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease, transform 0.2s ease;
}

.mya-act-btn:hover {
  background: $gn-blue;
  color: $gn-white;
  transform: translateY(-1px);
}

/* ---------------------------------------------------------
   Timeline / progress stepper
   --------------------------------------------------------- */

.mya-tl-panel {
  background: $gn-bg;
  border: 1px solid $gn-hair;
  border-top: none;
  padding: 28px 26px;
  margin-top: -16px;
  margin-bottom: 16px;
  border-radius: 0 0 20px 20px;
}

.mya-tl-header {
  font-size: 15px;
  font-weight: 600;
  color: $gn-navy;
  margin-bottom: 32px;
}

.mya-tl-appnum {
  color: $gn-body;
  font-weight: 400;
  margin-left: 8px;
}

.mya-stepper {
  overflow-x: auto;
}

.mya-stepper-track {
  display: flex;
  min-width: 700px;
  padding-top: 10px;
}

.mya-step {
  flex: 1;
  position: relative;
  text-align: center;
}

.mya-step-conn {
  position: absolute;
  top: 17px;
  left: -50%;
  width: 100%;
  height: 3px;
  background: $gn-hair;
  z-index: 1;
}

.mya-step-conn-fill {
  height: 100%;
  width: 0;
  background: $gn-blue-tint;
}

.mya-step-conn-fill--done {
  width: 100%;
  background: $gn-blue;
}

.mya-step-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: $gn-white;
  border: 2px solid $gn-hair;
  color: #9aa8bd;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  margin-bottom: 12px;
  font-size: 14px;
}

.mya-step--done .mya-step-circle,
.mya-step--active .mya-step-circle {
  border-color: $gn-blue;
  color: $gn-white;
  background: $gn-blue;
}

.mya-step--active .mya-step-circle {
  background: $gn-white;
  color: $gn-blue;
}

.mya-step--decline .mya-step-circle {
  border-color: $gn-red;
  background: $gn-red;
  color: $gn-white;
}

.mya-step-label {
  font-size: 13px;
  font-weight: 500;
  color: $gn-navy;
}

.mya-step-date {
  font-size: 12px;
  font-weight: 400;
  color: $gn-body;
  margin-top: 4px;
}

.mya-step-date--pending {
  color: #9aa8bd;
}

/* ---------------------------------------------------------
   Modal — same recipe as the homepage confirmation dialog:
   blurred navy overlay, pop-in card, pill footer buttons.
   --------------------------------------------------------- */

.mya-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 37, 64, 0.55);
  backdrop-filter: blur(4px);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  animation: gnFadeIn 0.2s ease-out;
}

.mya-modal {
  background: $gn-white;
  border-radius: 24px;
  width: 100%;
  max-width: 800px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 30px 60px rgba(10, 37, 64, 0.22);
  animation: gnPopIn 0.24s cubic-bezier(0.34, 1.56, 0.64, 1);
  overflow: hidden;
}

.mya-mhdr {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 28px;
}

.mya-mhdr-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.mya-mhdr-av {
  width: 48px;
  height: 48px;
  background: $gn-blue-soft;
  border-radius: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  color: $gn-blue;
}

.mya-mhdr-title {
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: $gn-navy;
}

.mya-mhdr-sub,
.mya-mbanner-date {
  font-size: 13.5px;
  font-weight: 400;
  color: $gn-body;
}

.mya-mhdr-close {
  width: 34px;
  height: 34px;
  background: none;
  border: none;
  border-radius: 50%;
  font-size: 17px;
  color: $gn-body;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.18s ease, color 0.18s ease;
}

.mya-mhdr-close:hover {
  background: $gn-blue-soft;
  color: $gn-navy;
}

.mya-mbanner {
  background: $gn-bg;
  padding: 14px 28px;
  border-top: 1px solid $gn-hair;
  border-bottom: 1px solid $gn-hair;
  display: flex;
  align-items: center;
  gap: 16px;
}

.mya-mtabs {
  display: flex;
  padding: 0 28px;
  border-bottom: 1px solid $gn-hair;
  gap: 22px;
  overflow-x: auto;
}

.mya-mtab {
  background: none;
  border: none;
  padding: 16px 2px;
  font-family: $gn-font;
  font-size: 14px;
  font-weight: 500;
  color: $gn-body;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: color 0.18s ease;
}

.mya-mtab:hover {
  color: $gn-navy;
}

.mya-mtab.active {
  color: $gn-blue;
  border-bottom-color: $gn-blue;
  font-weight: 600;
}

.mya-mtab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  margin-left: 6px;
  border-radius: 999px;
  background: $gn-blue-soft;
  color: $gn-blue;
  font-size: 11px;
  font-weight: 600;
}

.mya-mbody {
  padding: 26px 28px;
  overflow-y: auto;
  flex: 1;
}

.mya-sec-title {
  font-size: 15.5px;
  font-weight: 600;
  color: $gn-navy;
  margin-bottom: 18px;
  border-bottom: 1px solid $gn-hair;
  padding-bottom: 10px;
}

.mya-divider {
  height: 1px;
  background: $gn-hair;
  margin: 4px 0 28px;
}

.mya-view-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.mya-vflabel {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: $gn-blue;
  opacity: 0.75;
  margin-bottom: 5px;
}

.mya-vfvalue {
  font-size: 14px;
  color: $gn-navy;
  font-weight: 500;
}

.mya-prose-field {
  margin-bottom: 22px;
}

.mya-prose-val {
  font-size: 14px;
  font-weight: 400;
  color: $gn-body;
  background: $gn-bg;
  padding: 18px;
  border-radius: 16px;
  border: 1px solid $gn-hair;
  margin-top: 8px;
  line-height: 1.6;
}

.mya-no-attach {
  text-align: center;
  padding: 40px 20px;
  color: $gn-body;
}

.mya-no-attach i {
  font-size: 32px;
  color: $gn-blue-tint;
  margin-bottom: 12px;
  display: block;
}

.mya-attach-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mya-attach-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid $gn-hair;
  border-radius: 14px;
  background: $gn-white;
}

.mya-attach-ico {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: $gn-blue-soft;
  color: $gn-blue;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.mya-attach-info {
  flex: 1;
  min-width: 0;
}

.mya-attach-name {
  font-size: 14px;
  font-weight: 500;
  color: $gn-navy;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mya-attach-size {
  font-size: 12px;
  color: $gn-body;
  margin-top: 2px;
}

.mya-attach-dl {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: $gn-blue-soft;
  color: $gn-blue;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.18s ease, color 0.18s ease;
}

.mya-attach-dl:hover {
  background: $gn-blue;
  color: $gn-white;
}

.mya-mfooter {
  padding: 18px 28px;
  border-top: 1px solid $gn-hair;
  display: flex;
  justify-content: flex-end;
}

.mya-mfoot-close {
  background: $gn-white;
  border: 1px solid $gn-hair;
  padding: 10px 22px;
  border-radius: 999px;
  font-family: $gn-font;
  font-size: 14px;
  font-weight: 600;
  color: $gn-navy;
  cursor: pointer;
  box-shadow: $gn-shadow-card;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.mya-mfoot-close:hover {
  box-shadow: $gn-shadow-soft;
  transform: translateY(-1px);
}

/* ---------------------------------------------------------
   Empty state
   --------------------------------------------------------- */

.mya-empty-state {
  text-align: center;
  padding: 72px 24px;
  background: $gn-white;
  border-radius: 24px;
  border: 1px dashed $gn-blue-tint;
}

.mya-empty-ico {
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  border-radius: 50%;
  background: $gn-blue-soft;
  color: $gn-blue;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
}

.mya-empty-state h3 {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: $gn-navy;
  margin: 0 0 8px 0;
}

.mya-empty-state p {
  color: $gn-body;
  font-size: 14px;
  margin: 0;
}

/* ---------------------------------------------------------
   Motion & responsive
   --------------------------------------------------------- */

@keyframes gnFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes gnPopIn {
  from { opacity: 0; transform: scale(0.92) translateY(10px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .mya-overlay,
  .mya-modal,
  .mya-app-card,
  .mya-stat,
  .mya-act-btn { animation: none; transition: none; }
}

@media (max-width: 900px) {
  .mya-view-grid { grid-template-columns: 1fr; }
  .mya-page-title { font-size: 22px; }
}

@media (max-width: 620px) {
  .mya-wrap { padding: 28px 16px 48px; }
  .mya-card-body { padding: 18px 18px; gap: 14px; }
  .mya-col-actions { justify-content: flex-start; min-width: 0; }
  .mya-stat { flex: 1 1 100%; max-width: none; }
  .mya-modal { border-radius: 18px; }
  .mya-mbody { padding: 20px; }
  .mya-mtabs { padding: 0 20px; }
  .mya-mhdr, .mya-mbanner, .mya-mfooter { padding-left: 20px; padding-right: 20px; }
}

sp_widget.script:
(function () {


  data.applications = [];
  data.timelines    = {};

  var applicantTable = 'x_enno_gatenow_service_applicants';
  var currentUser    = gs.getUserName();
  if (!currentUser) return;

  var formatDate = function (d) {
    if (!d || d === '' || d === 'null') return '';
    var parts = String(d).split(' ')[0].split('-');
    if (parts.length === 3) {
      var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      return parts[2] + ' ' + months[parseInt(parts[1], 10) - 1] + ' ' + parts[0];
    }
    return String(d).split(' ')[0];
  };

  var formatCurrency = function(amount) {
    var num = parseFloat(amount);
    if (isNaN(num)) return '$0';
    if (num >= 1000000) {
      return '$' + (num / 1000000).toFixed(1) + 'M';
    } else if (num >= 1000) {
      return '$' + Math.round(num / 1000) + 'K';
    }
    return '$' + num.toLocaleString();
  };

  function buildAppObject(applicantRec) {
    var stateVal = applicantRec.getValue('state') || 'new';
    var stateDisplay = applicantRec.getDisplayValue('state') || 'Submitted';

    // Treat completion/review/acknowledgment or award states uniformly for display
    if (stateVal === 'award_acknowledged' || stateVal === 'project_completed' || stateVal === 'review_completed' || stateVal === 'project_in_progress' || stateVal.indexOf('award') > -1) {
      stateDisplay = applicantRec.getDisplayValue('state') || 'Awarded';
    }

    return {
      sys_id:               applicantRec.getUniqueValue(),
      number:               applicantRec.getValue('number')                         || '',
      first_name:           applicantRec.getValue('first_name')                     || '',
      middle_name:          applicantRec.getValue('middle_name')                    || '',
      last_name:            applicantRec.getValue('last_name')                      || '',
      birthdate:            formatDate(applicantRec.getValue('birthdate')),
      phone:                applicantRec.getValue('phone_number')                   || '',
      email:                applicantRec.getValue('email')                          || '',
      gender_display:       applicantRec.getDisplayValue('gender')                  || '',
      marital_display:      applicantRec.getDisplayValue('marital_status')          || '',
      race_display:         applicantRec.getDisplayValue('race')                    || '',
      ethnicity_display:    applicantRec.getDisplayValue('ethnicity')               || '',
      education_display:    applicantRec.getDisplayValue('education_level')         || '',
      military_display:     applicantRec.getDisplayValue('military_status')         || '',
      street:               applicantRec.getValue('street')                         || '',
      city:                 applicantRec.getValue('city')                           || '',
      country:              applicantRec.getValue('country')                        || '',
      zip:                  applicantRec.getValue('zip_postal_code')                || '',
      applicant_type_display: applicantRec.getDisplayValue('applicant_type')        || '',
      citizenship_display:    applicantRec.getDisplayValue('citizenship_status')      || '',
      identity_display:     applicantRec.getDisplayValue('identity_type')           || '',
      tribal_display:       applicantRec.getDisplayValue('tribal_affiliation')      || '',
      disability_display:   applicantRec.getDisplayValue('disability_status')       || '',
      ssn:                  applicantRec.getValue('ssn')                            || '',
      tin_ein:              applicantRec.getValue('tin_ein')                        || '',
      uei:                  applicantRec.getValue('uei')                            || '',
      organization:         applicantRec.getValue('organization')                   || '',
      start_date:           formatDate(applicantRec.getValue('project_start_date')),
      end_date:             formatDate(applicantRec.getValue('project_end_date')),
      submission_date:      formatDate(applicantRec.getValue('submission_date')),
      requested_budget:     formatCurrency(applicantRec.getValue('requested_budget')),
      short_description:    applicantRec.getValue('short_description')              || '',
      proposal_description: applicantRec.getValue('proposal_description')           || '',
      project_goals:        applicantRec.getValue('project_goals_and_objectives')   || '',
      project_activities:   applicantRec.getValue('project_activities_methodology') || '',
      state_display:        stateDisplay,
      updated_on:           applicantRec.getDisplayValue('sys_updated_on')          || ''
    };
  }

  // ── Maps ──────────────────────────────────────────────────────────────────
  var labelMap = {
    'new':                    'Application Created',
    'ready_for_review':       'Ready for Review',
    'review_in_progress':     'Review in Progress',
    'review_completed':       'Review Completed',
    'award_pending':          'Award Pending',
    'award_acknowledged':     'Award Acknowledged',
    'project_in_progress':    'Project in Progress',
    'project_completed':      'Project Completed',
    'closed':                 'Closed',
    'declined_by_agency':     'Declined by Agency',
    'declined_by_applicant':  'Declined by Applicant'
  };

  var colorMap = {
    'new':                    '#9ca3af',
    'ready_for_review':       '#3b82f6',
    'review_in_progress':     '#f59e0b',
    'review_completed':       '#8b5cf6',
    'award_pending':          '#f97316',
    'award_acknowledged':     '#22c55e',
    'project_in_progress':    '#6366f1',
    'project_completed':      '#0ea5e9',
    'closed':                 '#64748b',
    'declined_by_agency':     '#ef4444',
    'declined_by_applicant':  '#ef4444'
  };

  var badgeMap = {
    'new':                    'badge-new',
    'ready_for_review':       'badge-review',
    'review_in_progress':     'badge-in-progress',
    'review_completed':       'badge-completed',
    'award_pending':          'badge-pending',
    'award_acknowledged':     'badge-completed',
    'project_in_progress':    'badge-in-progress',
    'project_completed':      'badge-completed',
    'closed':                 'badge-closed',
    'declined_by_agency':     'badge-declined',
    'declined_by_applicant':  'badge-declined'
  };

  var normalStates = [
    'new',
    'ready_for_review',
    'review_in_progress',
    'review_completed',
    'award_pending',
    'award_acknowledged',
    'project_in_progress',
    'project_completed',
    'closed'
  ];

  // ── Query applications ────────────────────────────────────────────────────
  var applicantQuery = new GlideRecordSecure(applicantTable);
  if (currentUser !== 'admin') {
    applicantQuery.addQuery('sys_created_by', currentUser);
  }
  applicantQuery.orderByDesc('sys_updated_on');
  applicantQuery.query();

  while (applicantQuery.next()) {
    var sysId     = applicantQuery.getUniqueValue();
    var stateVal  = applicantQuery.getValue('state') || 'new';
    var createdOn = applicantQuery.getDisplayValue('sys_created_on') || '';

    // ── Attachments ──────────────────────────────────────────────────────────
    var attachments     = [];
    var attachmentQuery = new GlideRecordSecure('sys_attachment');
    attachmentQuery.addQuery('table_name',   applicantTable);
    attachmentQuery.addQuery('table_sys_id', sysId);
    attachmentQuery.query();

    while (attachmentQuery.next()) {
      attachments.push({
        sys_id:       attachmentQuery.getUniqueValue(),
        name:         attachmentQuery.getValue('file_name')    || '',
        size:         attachmentQuery.getValue('size_bytes')   || '0',
        content_type: attachmentQuery.getValue('content_type') || ''
      });
    }

    var appObj              = buildAppObject(applicantQuery);
    appObj.program_name     = applicantQuery.getDisplayValue('program.program_name')          || 'N/A';
    appObj.program_num      = applicantQuery.getDisplayValue('program.number')   || '';
    appObj.program_category = applicantQuery.getDisplayValue('program_category') || '';
    appObj.badge_class      = badgeMap[stateVal]                                 || 'badge-new';
    appObj.created_on       = createdOn;
    appObj.attachments      = attachments;
    appObj.state_value      = stateVal;

    data.applications.push(appObj);

    // ── Build stepper steps ────────
    var isDeclined    = (stateVal === 'declined_by_agency' || stateVal === 'declined_by_applicant');
    var currentIdx    = normalStates.indexOf(stateVal);
    var timelineSteps = [];

    if (isDeclined) {
      var previousState = 'new';

      var histGR = new GlideRecordSecure('sys_history_line');
      histGR.addQuery('set.id', sysId); 
      histGR.addQuery('field', 'state');
      histGR.addQuery('new', labelMap[stateVal] || stateVal);
      histGR.orderByDesc('sys_created_on');
      histGR.setLimit(1);
      histGR.query();

      if (histGR.next()) {
        var oldDisplayValue = histGR.getValue('old');
        for (var key in labelMap) {
            if (labelMap[key] === oldDisplayValue) {
                previousState = key;
                break;
            }
        }
      }

      var failIdx = normalStates.indexOf(previousState);
      if (failIdx === -1) failIdx = 0;

      normalStates.forEach(function (s, idx) {
        if (idx < failIdx) {
          timelineSteps.push({
            state:  s,
            label:  labelMap[s],
            color:  colorMap[s],
            status: 'completed'
          });
        } else if (idx === failIdx) {
          timelineSteps.push({
            state:  stateVal, 
            label:  labelMap[stateVal] || stateVal,
            color:  colorMap[stateVal] || '#ef4444',
            status: 'current'
          });
        } else {
          timelineSteps.push({
            state:  s,
            label:  labelMap[s],
            color:  '#9ca3af',
            status: 'pending'
          });
        }
      });

    } else {
      normalStates.forEach(function (s, idx) {
        timelineSteps.push({
          state:  s,
          label:  labelMap[s],
          color:  colorMap[s],
          status: idx < currentIdx    ? 'completed'
                : idx === currentIdx ? 'current'
                :                      'pending'
        });
      });
    }

    data.timelines[sysId] = timelineSteps;
  }

})();
